        "correcta": 0,
        "explicacion": "La Sala Primera del Tribunal Supremo es la de lo Civil; la Segunda es de lo Penal, la Tercera de lo Contencioso-Administrativo, la Cuarta de lo Social y la Quinta de lo Militar.",
